css:
.p07-e { --frame-w: var(--w2); }
.p07-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p07-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) 0; }
.p07-err .banner { width: 100%; }
.p07-top { display: grid; gap: var(--s-2); }
.p07-top:empty { display: none; }
.p07-btnwrap { position: relative; display: inline-block; }
.p07-tip { position: absolute; z-index: 30; width: max-content; max-width: 17.5rem; }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p07-expl { flex: 1; display: grid; gap: var(--s-1); max-width: var(--measure); }

.p07-wrap { max-width: 56rem; margin-inline: auto; display: grid; gap: var(--s-4); }
.p07-list { display: grid; }
.p07-hz { display: grid; gap: var(--s-2); align-content: start; }
.p07-hz + .p07-hz { margin-top: var(--s-4); padding-top: var(--s-4); border-top: var(--w1) solid var(--rule); }
.p07-hz__head { display: grid; }
.p07-empty { color: var(--text-2); padding: var(--s-1) 0; }
.p07-add { position: relative; display: flex; flex-wrap: wrap; align-items: flex-start; gap: var(--s-2); }
.p07-add .banner { flex: 1 1 100%; }
.p07-val { display: grid; grid-template-columns: 3.25rem 2rem; align-items: center; justify-content: end; column-gap: var(--s-1); }
.p07-date { text-align: end; }
.p07-tbtn { display: flex; align-items: center; width: 100%; min-height: var(--hit); padding: 0; border: 0; background: none; text-align: start; cursor: pointer; }
.p07-list .check { min-width: var(--hit); justify-content: center; }
.p07-list .check input:disabled:checked + .check__box { background-color: var(--line); border-color: var(--line); }
.p07-list .ibtn[aria-disabled="true"] { border-color: transparent; }
.p07-hov { position: relative; display: inline-grid; }
.p07-acts { display: inline-flex; align-items: center; gap: var(--s-2); }
.p07-ord { display: inline-flex; align-items: center; gap: var(--s-1); margin-inline-end: var(--s-2); opacity: 0; }
.p07-list .rec:hover .p07-ord, .p07-list .rec:focus-within .p07-ord, .p07-ord.is-shown { opacity: 1; }
@media (hover: none) { .p07-ord { opacity: 1; } }   
.p07-more { display: none; }
.p07-menuwrap { position: relative; display: inline-grid; }
.p07-rowmenu { position: absolute; z-index: 30; right: 0; top: calc(100% + var(--s-1)); min-width: 14rem; }
.p07-slot { width: var(--hit); height: var(--hit); flex: none; }
.p07-tip-r { right: 0; bottom: calc(100% + var(--s-1)); }
.p07-tip-l { left: calc(100% + var(--s-1)); top: 50%; translate: 0 -50%; }
.p07-note { padding: var(--s-2) var(--s-3); font-size: var(--fs-small); line-height: var(--lh-small); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {

  .p07-list .rec { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "lead body actions" "lead value actions"; }
  .p07-acts { display: none; }
  .p07-more { display: inline-grid; }
  .p07-list .rec__lead { align-self: start; }
  .p07-list .rec__value { text-align: start; justify-self: start; }
  .p07-val { display: flex; justify-content: flex-start; align-items: center; gap: var(--s-1); }
  .p07-date { text-align: start; margin-inline-end: var(--s-1); }
  .p07-list .rec--sub { margin-inline-start: var(--s-3); }
  .p07-slot { display: none; }
  .p07-hov { position: static; }
}


.p07-scrolled .p07-hz:not(:last-child) { display: none; }
.p07-scrolled .p07-hz + .p07-hz { margin-top: 0; padding-top: 0; border-top: 0; }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p07-shift .p07-wrap { margin-top: calc(var(--p07-shift, 0rem) * -1); } }
